window.CURTAIN_EXHIBITS = [
  {id:'wand',name:'现代短杖',kind:'施法工具',number:'01',shape:'wand',tag:'导出 · 精准',lead:'短杖轻便，适合在近距离和复杂地形中施法。',facts:[['工作方式','协助施法者导出力量'],['使用场景','近距离、复杂地形'],['时代','现代咒语时代']],chapters:[
    {title:'握在手里的路径',paragraphs:['短杖适合城市中的距离。门框、转角和并肩站立的同伴，把施法的空间切得很细。巫师握住杖柄，让力量沿工具导出，动作随眼前的目标调整。这种便于携带的形制，也适应了现代咒语对速度和精确度的要求。','展台旁放着一页练习稿：同一句咒文分了几次书写，末尾的笔迹渐渐放松。学徒练习时，口中的节奏、回路的负荷与手上的动作要慢慢配合。学徒还要适应杖身长度带来的姿势变化，经过长时间练习才能熟练。']},
    {title:'从长杖时代走来',paragraphs:['古代魔法有较长的吟唱与引导，长杖为远距离导出和自然共鸣提供条件。城市成长以后，巫师面对的地形与战斗节奏发生变化，短杖逐渐成为现代巫师社会的标准工具。长杖也仍有适合它的用途。']}
  ],sources:['施法工具演变','现代咒语','施法原理'],links:['wands','casting-reference','daily-apprentice']},
  {id:'staff',name:'古式长杖',kind:'施法工具',number:'02',shape:'staff',tag:'共鸣 · 远距',lead:'古式长杖有较长的导出路径，适合古代魔法的施法方式。',facts:[['导出路径','较长'],['适用传统','古代魔法'],['回路负担','较重']],chapters:[
    {title:'开阔地上的工具',paragraphs:['长杖时代的施法常面对遥远的目标。巫师有时间站定、吟唱，让自然力量在较长的路径上得到引导。长杖的自然共鸣与远距离引导效率，适合这样的场面。宽阔的地面为队伍留下间隔，也给缓慢成形的法术留出距离。','把长杖放进一条狭巷，许多动作便显得局促。转身要顾及墙壁，同行者要让开位置；吟唱尚未结束，近处的情况可能已经改变。在这样的地方使用长杖，施法者需要格外留意周围。']},
    {title:'留在杖外的代价',paragraphs:['古代魔法会给回路带来很大负荷，长时间的引导也需要施法者持续维持状态。这样的工具适合相应的魔法与使用者。后来短杖普及，长杖仍留在一部分专精古魔法者的手中，他们继续运用自己熟悉的节奏。']}
  ],sources:['施法工具演变','古代魔法'],links:['wands','old-and-modern-spells','casting-reference']},
  {id:'stone',name:'封咒蕴法石',kind:'魔法矿物',number:'03',shape:'stone',tag:'完整咒语 · 单次消耗',lead:'从矿山运出的石材，经填充以后，才有了可以调用的咒语。',facts:[['保存内容','完整咒语'],['释放效果','无损耗重新释放'],['使用以后','已使用部分不能再次填咒']],chapters:[
    {title:'同一块石头的两种身价',paragraphs:['原石离开矿山时，带着开采、运输和分拣的成本。填充者将完整咒语封入石材，才使它进入工坊与使用者的工作安排。埃斯佩兰萨输出大量原料，卡莫瑞亚汇集高级巫师；石材从原料到填充，经过开采者与巫师之手。','石材的体量与容纳的咒语体量有关。复杂咒语占用更多材料；同一块完整石头混入不同咒语，又会使它们相互影响、抵消。填充者需要提前选定咒语。']},
    {title:'炉火如何接续',paragraphs:['工坊可以在大块蕴法石中预存大量同一咒语，机器逐次调用，连续产生所需的效果。储量影响一段工作能维持多久。有人准备材料，有人填充咒语，工人在机器旁安排下一轮加工；这些工作要跟上机器消耗储量的速度。']}
  ],sources:['蕴法石','卡莫瑞亚','埃斯佩兰萨','生产力与农业'],links:['stone','food-and-work','world-trade']},
  {id:'spent',name:'用过的蕴法石',kind:'回收材料',number:'04',shape:'spent',tag:'残余结构 · 二次流转',lead:'咒语释放后，用过的石材还可以回收利用。',facts:[['再次封咒','已使用部分不可重新填充'],['后续去向','建材、研磨料、炼金原料'],['交易规模','小规模二级市场']],chapters:[
    {title:'从工作台上收下来',paragraphs:['工人将用过的石材从设备旁收起，新的储备接上原先的工作。曾承载魔法的石头，内部结构已经发生变化；这种变化使它在某些用途上仍有价值。废石有了新的分拣办法，收料者要问清它曾经承载的咒语和预备送去的地方。','曾经承载防御性咒语的废石，可以在建材中提供被动防护；另一些进入工具加工所需的研磨料，少量流向炼金原料的交易。这些去向养活了一小批中间商。他们需要熟悉不同废石的用途。']},
    {title:'一段尚未结束的流转',paragraphs:['矿山、填充者、工坊与回收者先后经手这些石材，各有不同的用途。用过的石头从能源储备转入材料市场，也使一间工坊与附近的收料铺有了长期往来。下次送货的人来时，可能同时带来新石，也带走墙边积攒的旧料。']}
  ],sources:['蕴法石','生产力与农业'],links:['stone','food-and-work','daily-market']},
  {id:'lamp',name:'一盏日用造物灯',kind:'巫师造物',number:'05',shape:'lamp',tag:'重复使用 · 自然恢复',lead:'这盏日用造物灯可以重复使用，也能缓慢恢复储备。',facts:[['保存内容','已塑形的魔力与塑形方式'],['恢复方式','缓慢自然恢复'],['使用效果','受持有者契合度影响']],chapters:[
    {title:'一件日用造物的样本',paragraphs:['这盏灯取日用照明为例，展示造物如何进入生活。器物保存了已塑形的魔力与塑形方式，让某种效果能够重复使用。主人将它从书桌搬到柜台，照明也随之换了位置。','造物与持有者之间有契合度的差别。材料、灌注的魔力流与使用者的回路特性共同影响能效，无魔力者也可能使用造物。挑选工具时，亲手试过的感受因而很有分量：同一件器物，在不同人的手中可以有不同的表现。']},
    {title:'等它慢慢恢复',paragraphs:['造物从自然魔力中缓慢恢复储备。人为补充需要初步塑形的魔力，并使魔力流与内部一致，因此通常只有原灌注者能够完成。日用器物的主人更多依靠自然恢复，在使用与等待之间安排工作。需要继续照明时，主人也得考虑恢复所需的时间。']}
  ],sources:['造物体系','生产力与农业'],links:['artefacts-study','daily-tools','daily-apprentice']},
  {id:'gate',name:'界门结构样本',kind:'圣律造物',number:'06',shape:'gate',tag:'空间网络 · 登记管理',lead:'界门连接不同地区，由魔法联合部维护和监管。',facts:[['造物类别','大型圣律造物'],['建造者','空间魔法体系的巅峰巫师合力建造'],['维护监管','魔法联合部']],chapters:[
    {title:'一座城市通向远处的门',paragraphs:['界门出现在首都、大型城市、战略要地和联合部控制的区域。它的建造需要空间魔法体系巅峰巫师合力完成，之后持续受到维护与监管。地图上的几个城市因它而建立联系，城门外的乡镇仍有自己的道路与行程。','界门的使用费用使它更常出现在贵族、官员、高阶巫师、商人和军方的生活中。对其他人来说，远方更多地出现在来信和货物中。一个普通居民可能终身没有离开出生的大陆，远处矿山的石料却已沿贸易链来到他工作的地方。']},
    {title:'登记册中的器物',paragraphs:['圣律造物受到严格管理，持有与转让都要登记。界门作为大型公共空间设施，又与日常的城市秩序相连。维护的人、安排通行的人与等待出发的人，各自围绕这件庞大的造物工作。通行的安排也会影响旅程所需的时间。']}
  ],sources:['界门','造物体系','魔法联合部'],links:['gates','daily-journey','ministry-government']}
];
